function Find-InTree {
  param([string]$treeSha, [string]$rel)
  $raw = Get-GitObject $treeSha
  if ($raw -eq $null) { return "MISSING-TREE:$treeSha" }
  $text = [System.Text.Encoding]::UTF8.GetString($raw)
  # tree entries: "<mode> <name>\0<20-byte sha>"
  $entries = New-Object System.Collections.ArrayList
  $pos = 0
  while ($pos -lt $text.Length) {
    $nul = $text.IndexOf([char]0, $pos)
    if ($nul -lt 0) { break }
    $hdr = $text.Substring($pos, $nul - $pos)
    $sp = $hdr.IndexOf(' ')
    $mode = $hdr.Substring(0,$sp); $name = $hdr.Substring($sp+1)
    $shaBytes = $raw[$nul+1 .. ($nul+20)]
    $shaHex = -join ($shaBytes | ForEach-Object { $_.ToString('x2') })
    [void]$entries.Add([pscustomobject]@{mode=$mode;name=$name;sha=$shaHex})
    $pos = $nul + 21
  }
  $out = @()
  foreach ($e in $entries) {
    $full = if ($rel) { "$rel/$($e.name)" } else { $e.name }
    if ($e.mode -eq '40000' -or $e.mode -eq '040000') {
      $out += Find-InTree $e.sha $full
    } else {
      $out += $full
    }
  }
  return $out
}
