  $out = New-Object System.IO.MemoryStream
  $ds = New-Object System.IO.Compression.DeflateStream($fs, [System.IO.Compression.CompressionMode]::Decompress)
  $ds.CopyTo($out); $ds.Dispose(); $fs.Dispose()
  return $out.ToArray()
}
function Tree-Entries {
  param([string]$treeSha)
  $raw = Get-GitObject $treeSha
  if ($null -eq $raw) { throw "missing tree $treeSha" }
  $result = New-Object System.Collections.ArrayList
  $pos = 0
  $len = $raw.Length
  while ($pos -lt $len) {
    $nul = $pos
    while ($nul -lt $len -and $raw[$nul] -ne 0) { $nul++ }
    if ($nul -ge $len) { break }
    $hdrBytes = $raw[$pos .. ($nul - 1)]
    $hdr = [System.Text.Encoding]::UTF8.GetString([byte[]]$hdrBytes)
    $sp = $hdr.IndexOf(' ')
    $name = $hdr.Substring($sp + 1)
    $isDir = $hdr.StartsWith('40000')
    $shaBytes = [byte[]]$raw[($nul + 1) .. ($nul + 20)]
    $sb = New-Object System.Text.StringBuilder
    foreach ($b in $shaBytes) { [void]$sb.Append($b.ToString('x2')) }
    [void]$result.Add([pscustomobject]@{ name = $name; isDir = $isDir; sha = $sb.ToString() })
    $pos = $nul + 21
  }
  return $result
}
$all = New-Object System.Collections.ArrayList
function Walk {
  param([string]$sha, [string]$rel)
  foreach ($e in (Tree-Entries $sha)) {
    $full = if ($rel) { "$rel/$($e.name)" } else { $e.name }
    if ($e.isDir) { Walk $e.sha $full } else { [void]$all.Add($full) }
  }
}
